import { cn } from "@/lib/utils"

export function Marquee({ className, vertical = false, children }: { className?: string; vertical?: boolean; children: React.ReactNode }) {
  return (
    <div className={cn("group flex overflow-hidden [--duration:40s] [--gap:1rem]", className)}>
      <div className={cn("flex shrink-0 gap-(--gap)", vertical ? "animate-marquee-vertical flex-col" : "animate-marquee")}>
        {children}
      </div>
    </div>
  )
}
